import { expect, expectStatus, test } from "../../fixtures";

test.describe("vendor names are unique within a tenant", () => {
  test(
    "creating a vendor whose name differs only by case returns 409 vendor_name_taken",
    { tag: "@VEN-03" },
    async ({ apiAs }) => {
      // Arrange: a unique name so parallel runs never collide with each other.
      const member = await apiAs("member");
      const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
      const name = `Acme Freight ${suffix}`;

      const existing = await member.post("/api/vendors", {
        data: { name, category: "logistics", contact_email: `ops+${suffix}@acmefreight.example` },
      });
      await expectStatus(existing, 201);

      // Act: same name, different casing.
      const response = await member.post("/api/vendors", {
        data: {
          name: name.toLowerCase(),
          category: "logistics",
          contact_email: `ops+dup-${suffix}@acmefreight.example`,
        },
      });

      // Assert
      const body = await expectStatus(response, 409);
      expect(body.error.code).toBe("vendor_name_taken");
    },
  );
});
